check "PVC archive-restore is Bound to pv-archive" bash -c "[ \"\$(kubectl --context main -n records get pvc archive-restore -o jsonpath='{.status.phase} {.spec.volumeName} {.spec.storageClassName}')\" = 'Bound pv-archive archive' ]"
check "pv-archive still has reclaim policy Retain and is claimed by records/archive-restore" bash -c "[ \"\$(kubectl --context main get pv pv-archive -o jsonpath='{.spec.persistentVolumeReclaimPolicy} {.spec.claimRef.namespace}/{.spec.claimRef.name} {.status.phase}')\" = 'Retain records/archive-restore Bound' ]"
check "pod archive-reader is Running with the volume at /archive" bash -c "pod_ready main archive-reader records && [ \"\$(kubectl --context main -n records get pod archive-reader -o jsonpath='{.spec.volumes[?(@.persistentVolumeClaim.claimName==\"archive-restore\")].name}')\" != '' ]"
check "the old data is readable at /archive/marker.txt" bash -c "kubectl --context main -n records exec archive-reader -- cat /archive/marker.txt | grep -q 'checksum=7f3a9c'"
